DROP TABLE IF EXISTS `device_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_template` (
  `device_tmpl_id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备模板ID',
  `face_plate_id` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '关联fuxa表的id',
  `alarm_code` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '报警策略(关联alarm表的alarm_name字段)。例如：Communication_status_00',
  `device_tmpl_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '设备模板名称',
  `n4_name` varchar(100) COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT 'N4 name',
  `device_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '产品类型：变压器/列间空调/多功能电表/湿膜加湿器/温湿度传感器/氢气探测器/漏水报警器/直流屏/UPS/蓄电池等（标准英文缩写，用于生成设备码）',
  `model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '产品型号和规格',
  `purpose` varchar(100) COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT 'purpose',
  `manufacturer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '制造商',
  `functional_area` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '功能区域（区分相同型号但点位不同的设备）',
  `manu_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '生产日期（格式：year/mon/day）',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标记',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`device_tmpl_id`) USING BTREE,
  UNIQUE KEY `uk_device_tmpl_name` (`device_tmpl_name`) USING BTREE COMMENT '设备模板名称唯一（模板名中已包含设备类型）',
  KEY `idx_device_type` (`device_type`) USING BTREE,
  KEY `idx_alarm_code` (`alarm_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs ROW_FORMAT=DYNAMIC COMMENT='设备模板表';
/*!40101 SET character_set_client = @saved_cs_client */;

