CREATE TABLE `alarm_rule_numeric` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '涓婚敭ID',
  `alarm_name` varchar(200) COLLATE utf8mb4_0900_as_cs NOT NULL,
  `point_type` varchar(20) COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '鐐逛綅绫诲瀷',
  `time_delay` int DEFAULT '0' COMMENT 'time delay',
  `deadband` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT 'deadband',
  `high_high_value` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_high_severity` varchar(20) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_high_message` varchar(500) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_high_hysteresis` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_value` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_severity` varchar(20) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_message` varchar(500) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `high_hysteresis` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_value` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_severity` varchar(20) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_message` varchar(500) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_hysteresis` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_low_value` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_low_severity` varchar(20) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_low_message` varchar(500) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `low_low_hysteresis` varchar(50) COLLATE utf8mb4_0900_as_cs DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '閫昏緫鍒犻櫎鏍囪?',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_alarm_name` (`alarm_name`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs COMMENT='Numeric 绫诲瀷鎶ヨ?瑙勫垯琛';
